import time
import logging
from .message_proxy import MessageProxy
from .message_verification import MessageVerification
from .message_flow_alias_store import MessageFlowAliasStore
from .exceptions import VerifyMessagesFailure


class MTKMessageFacade(object):

    def __init__(self):
        self._message_proxy = None
        self._message_verification = MessageVerification()
        self._message_flow_alias_store = MessageFlowAliasStore()

    def setup(self, pyro_ip, pyro_port):
        self._message_proxy = MessageProxy(pyro_ip, pyro_port)

    def create_message_flow_alias(self, flow_alias, message_type, **kwargs):
        self._message_proxy.create_proxy(flow_alias)
        self._message_flow_alias_store.add_flow_alias(flow_alias, message_type, **kwargs)

    def expect_messages_in_flow(self, awaited_messages, flow_alias, timeout=3):
        message_type, message_config_parameters = self._message_flow_alias_store.get_flow_alias_by_name(flow_alias)
        read_message_function = self._message_proxy.get_read_message_function(message_type)
        self._message_verification.add_awaited_messages(awaited_messages)
        self._verify_message(read_message_function, flow_alias, message_config_parameters, timeout)
        all_verified_messages = self._message_verification.get_all_verified_messages()
        if not self._is_verified_successfully():
            raise VerifyMessagesFailure("{} not in {}".format(awaited_messages, all_verified_messages))
        logging.info("verified messages: {}".format(all_verified_messages))

    def _verify_message(self, read_function, flow_alias, config_parameters, timeout):
        end_time = time.time() + timeout
        while time.time() < end_time:
            messages = read_function(flow_alias, **config_parameters)
            self._message_verification.verify_messages(messages)
            if self._is_verified_successfully():
                break

    def _is_verified_successfully(self):
        verify_results = self._message_verification.get_verify_result()
        for _, result in verify_results:
            if not result:
                return False
        return True

    def get_latest_messages_in_flow(self, flow_alias, timeout=3):
        message_type, message_config_parameters = self._message_flow_alias_store.get_flow_alias_by_name(flow_alias)
        read_message_function = self._message_proxy.get_read_message_function(message_type)
        messages = []
        end_time = time.time() + timeout
        while time.time() < end_time:
            messages = read_message_function(flow_alias, **message_config_parameters)
            if messages:
                break
        return messages

    def teardown(self):
        pass
